+/// The execution trust model selected for an intent.
+#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
+#[serde(rename_all = "camelCase")]
+pub enum ExecutionTrustProfileV1 {
+    GitCommit,
+    HermeticContent,
+}
